// --- Write all outputs --------------------------------------------------
function write(path, body) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, body, "utf8");
}

write("spec/15-wp-plugin-how-to/skeletons/00-overview.md", generatePhpIndex());
write("spec/15-wp-plugin-how-to/skeletons/php/Enums.generated.php", generatePhpEnums());
write("spec/15-wp-plugin-how-to/skeletons/php/RestRoutes.generated.php", generatePhpRoutes());
write("spec/32-ui-design/skeletons/00-overview.md", generateTsIndex());
write("spec/32-ui-design/skeletons/ts/enums.generated.ts", generateTsEnums());
write("spec/32-ui-design/skeletons/ts/api-client.generated.ts", generateTsApiClient());

console.log(
  `✅ skeletons written: ${contract.enums.length} enums × 2 langs, ${contract.endpoints.length} endpoints × 2 langs`,
);
